local BaseEffect = import('Game.Chapter.NewChapterEffect.BaseEffect')
local base = BaseEffect

local CustomLightIntensity = CS.CustomLightIntensity

---@class CharacterDarkenEffect : BaseEffect
local CharacterDarkenEffect = Class("CharacterDarkenEffect", BaseEffect)

local NewChapterConstants = import("Game.Chapter.NewChapterConstants")

function CharacterDarkenEffect:__init()
end

function CharacterDarkenEffect:__delete()
end

function CharacterDarkenEffect:Initialize(parameters)
    base.StartEffect(self, parameters)
    if parameters.effect ~= NewChapterConstants.CharacterEffect.Darken then
        return
    end
end

function CharacterDarkenEffect:StartEffect(object)
    base.StartEffect(self, object)
    local character = object.transform:Find(NewChapterConstants.CharacterName)
    if isNull(character) then
        return
    end
    local light = object.gameObject:EnsureComponent(typeof(CustomLightIntensity))
    light.Intensity = 0.2
    light.enabled = true
end

function CharacterDarkenEffect:IsFinish()
    base.IsFinish(self)
    return true
end

function CharacterDarkenEffect:EndEffect(object)
    base.EndEffect(self, object)
end

function CharacterDarkenEffect:RemoveEffect(object)
    base.RemoveEffect(self, object)
    local character = object.transform:Find(NewChapterConstants.CharacterName)
    if isNull(character) then
        return
    end
    local light = object.gameObject:EnsureComponent(typeof(CustomLightIntensity))
    light.enabled = false
end

return CharacterDarkenEffect